"""Exact failure probability and parameter selection for random hashing.

The failure probability of a uniformly random codebook against k competitors is
EXACTLY  1 - (1 - 1/M)^k.  This module evaluates it in exact rational
arithmetic, compares it with the union and Bonferroni bounds, and inverts it to
select the smallest codebook size meeting a reliability target.
"""

from __future__ import annotations

from fractions import Fraction


def exact_failure_probability(k: int, m: int) -> Fraction:
    """1 - (1 - 1/M)^k, in exact rational arithmetic."""
    if m <= 0:
        raise ValueError("codebook size must be positive")
    return 1 - Fraction(m - 1, m) ** k


def union_bound(k: int, m: int) -> Fraction:
    """The classical union bound k/M (an upper bound on the exact value)."""
    return Fraction(k, m)


def bonferroni_bound(k: int, m: int) -> Fraction:
    """Bonferroni lower bound k/(2M), valid whenever 2(k-1) <= M."""
    return Fraction(k, 2 * m)


def minimal_codebook_size(k: int, epsilon: Fraction) -> int:
    """Smallest M with exact failure probability <= epsilon.

    Monotone in M, so binary search is exact and terminates in
    O(log(k/epsilon)) evaluations, each O(log k) multiplications.
    """
    lo, hi = 1, 1
    while exact_failure_probability(k, hi) > epsilon:
        hi *= 2
    while lo < hi:
        mid = (lo + hi) // 2
        if exact_failure_probability(k, mid) <= epsilon:
            hi = mid
        else:
            lo = mid + 1
    return lo


def blocked_minimal_codebook_size(t: int, b: int, epsilon: Fraction) -> int:
    """Smallest M such that the blocked union bound b(|T|-1)/M is <= epsilon."""
    if epsilon <= 0:
        raise ValueError("reliability target must be positive")
    target = Fraction(b * (t - 1)) / epsilon
    return -((-target.numerator) // target.denominator)   # ceiling


def report(k: int) -> None:
    print(f"competitors k = {k}")
    print(f"{'M':>8} {'exact':>14} {'union k/M':>12} {'Bonferroni':>12}")
    for m in (2, 4, 8, 16, 64, 256, 1024):
        e = exact_failure_probability(k, m)
        print(f"{m:>8} {float(e):>14.8f} {float(union_bound(k, m)):>12.8f}"
              f" {float(bonferroni_bound(k, m)):>12.8f}")
    for eps in (Fraction(1, 10), Fraction(1, 1000), Fraction(1, 10 ** 6)):
        m = minimal_codebook_size(k, eps)
        print(f"  reliability 1 - {float(eps):.0e}:  minimal M = {m}"
              f"  (log2 M = {m.bit_length() - 1}..{m.bit_length()} bits)")


if __name__ == "__main__":
    report(k=1023)
